    int64_t numel
) {
    int tid = threadIdx.x;
    int64_t idx = (int64_t)blockIdx.x * blockDim.x + tid;
    int64_t stride = (int64_t)blockDim.x * gridDim.x;

    float thread_sum = 0.0f;
    for (int64_t i = idx; i < numel; i += stride) {
        float diff = static_cast<float>(predictions[i]) - static_cast<float>(targets[i]);
        thread_sum += diff * diff;
    }

    // Warp-level reduction via shuffle
    unsigned mask = 0xffffffff;
    thread_sum += __shfl_down_sync(mask, thread_sum, 16);
    thread_sum += __shfl_down_sync(mask, thread_sum, 8);
    thread_sum += __shfl_down_sync(mask, thread_sum, 4);
    thread_sum += __shfl_down_sync(mask, thread_sum, 2);
    thread_sum += __shfl_down_sync(mask, thread_sum, 1);

    int warp_id = tid / 32;
    int lane_id = tid % 32;
    int num_warps = blockDim.x / 32;

    extern __shared__ float warp_sums[];
    if (lane_id == 0) {
        warp_sums[warp_id] = thread_sum;
    }
    __syncthreads();

    // First-warp finalize: load warp partial, reduce via shuffle, lane 0 atomicAdds
    if (tid < 32) {
        float block_sum = (tid < num_warps) ? warp_sums[tid] : 0.0f;
        block_sum += __shfl_down_sync(0xffffffff, block_sum, 8);
        block_sum += __shfl_down_sync(0xffffffff, block_sum, 4);
        block_sum += __shfl_down_sync(0xffffffff, block_sum, 2);
        block_sum += __shfl_down_sync(0xffffffff, block_sum, 1);
        if (tid == 0) {
            atomicAdd(output, block_sum);
        }
    }
}

torch::Tensor fused_mse_loss_cuda(torch::Tensor predictions, torch::Tensor targets) {
    int64_t numel = predictions.numel();

    const int threads = 512;
    // shared memory: one float per warp
    int num_warps = threads / 32;
    size_t smem = num_warps * sizeof(float);

    auto options = torch::TensorOptions().dtype(torch::kFloat32).device(predictions.device());
    // Zero-init output so atomicAdd starts from 0
    auto output = torch::zeros({1}, options);

    bool use_vec4 = (predictions.scalar_type() == at::ScalarType::Float) &&
                    (reinterpret_cast<uintptr_t>(predictions.data_ptr<float>()) % 16 == 0) &&
                    (reinterpret_cast<uintptr_t>(targets.data_ptr<float>()) % 16 == 0);

    if (use_vec4) {
        int64_t numel4 = numel / 4;
        int64_t grid_work = (numel4 > 0) ? numel4 : 1;
        const int blocks = (int)min((int64_t)((grid_work + threads - 1) / threads), (int64_t)512);

        mse_kernel_vec4<<<blocks, threads, smem>>>(
            predictions.data_ptr<float>(),
            targets.data_ptr<float>(),
            output.data_ptr<float>(),
            numel4,
            numel
        );
    } else {
        const int blocks = (int)min((int64_t)((numel + threads - 1) / threads), (int64_t)512);

        AT_DISPATCH_FLOATING_TYPES_AND2(
            at::ScalarType::Half, at::ScalarType::BFloat16,
            predictions.scalar_type(), "mse_kernel_partial", [&] {
                mse_kernel_partial<scalar_t><<<blocks, threads, smem>>>(
                    predictions.data_ptr<scalar_t>(),
                    targets.data_ptr<scalar_t>(),
                    output.data_ptr<float>(),
                    numel
                );
            }
        );
    }

    return output[0] / static_cast<float>(numel);
}
